  const VIDEO_BASE = "../sample-videos/";
  const KEY = "readyline-demo";
  const load = () => { try { return JSON.parse(localStorage.getItem(KEY)) || { regs: {}, results: [] }; } catch (e) { return { regs: {}, results: [] }; } };
  const save = d => { try { localStorage.setItem(KEY, JSON.stringify(d)); } catch (e) {} };
  const lang = v => CFG.LANGUAGES.indexOf(v) !== -1 ? v : CFG.LANGUAGES[0];
  const token = () => (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random());
  const linkFor = t => location.pathname + "?t=" + encodeURIComponent(t);

  function statuses(d, t) {
    const out = {};
    CFG.SESSIONS.forEach((s, i) => {
      const rows = d.results.filter(r => r.token === t && r.id === s.id);
      const passed = rows.some(r => r.passed);
      out[s.id] = { attempts: rows.length, passed: passed, allowed: CFG.MAX_ATTEMPTS,
        remaining: passed ? 0 : Math.max(0, CFG.MAX_ATTEMPTS - rows.length),
        unlocked: i === 0 || out[CFG.SESSIONS[i - 1].id].passed };
    });
    return out;
  }

  function call(p) {
    const d = load();
    const reply = x => new Promise(res => setTimeout(() => res(x), 250));
    if (p.action === "register" || p.action === "resend") {
      const email = String(p.email || "").trim().toLowerCase();
      let t = Object.keys(d.regs).find(k => d.regs[k].email === email);
      if (p.action === "resend") return reply(t ? { ok: true, demoLink: linkFor(t) } : { ok: true });
      if (!t) { t = token(); d.regs[t] = { first: p.firstName, last: p.lastName, email: email, lang: lang(p.language) }; save(d); }
      return reply({ ok: true, sent: true, demoLink: linkFor(t) });
    }
    const reg = d.regs[p.token];
    if (!reg) return reply({ ok: false, error: "bad_link" });
    const l = lang(p.language);
    const st = statuses(d, p.token);
    const s = CFG.SESSIONS.find(x => x.id === p.courseId);
    if (p.action === "lookup") {
      return reply({ ok: true, firstName: reg.first, lastName: reg.last, language: reg.lang, passPercent: CFG.PASS_PERCENT, statuses: st,
        sessions: CFG.SESSIONS.map(x => ({ id: x.id, version: x.version, title: x.title[l], minutes: x.minutes[l],
          questions: x.questions.map(q => ({ q: q[l].q, a: q[l].a })) })) });
    }
    if (!s) return reply({ ok: false, error: "unknown_course" });
    if (!st[s.id].unlocked) return reply({ ok: false, error: "locked" });
    if (p.action === "video") {
      const out = { ok: true, videoUrl: VIDEO_BASE + s.videos[l], expiresInSeconds: 43200 };
      if (s.captions && s.captions[l]) out.captionsUrl = VIDEO_BASE + s.captions[l];
      return reply(out);
    }
    if (p.action === "submit") {
      const before = st[s.id];
      if (before.passed) return reply({ ok: false, error: "already_passed", status: before });
      if (before.remaining <= 0) return reply({ ok: false, error: "no_attempts", status: before });
      let score = 0;
      s.questions.forEach((q, i) => { if (Number(p.answers[i]) === q.answer) score++; });
      const percent = Math.round(score / s.questions.length * 100), passed = percent >= CFG.PASS_PERCENT;
      d.results.push({ token: p.token, id: s.id, passed: passed }); save(d);
      const attempt = before.attempts + 1;
      return reply({ ok: true, score: score, total: s.questions.length, percent: percent, passed: passed, attempt: attempt,
        status: { attempts: attempt, allowed: before.allowed, remaining: passed ? 0 : before.remaining - 1, passed: passed, unlocked: true } });
    }
    return reply({ ok: false, error: "bad_request" });
  }

  window.ReadyLineDemo = { call: call };
